slot.css:
.cc-scope .part { width: 260px; padding: 16px 18px; border: 1px solid var(--line); border-radius: 12px; background: var(--panel); font-family: var(--font-mono); color: var(--text) }
.cc-scope .lbl { font-size: 15px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase }
.cc-scope .st { margin-top: 10px; font-size: 13px; font-weight: 700; letter-spacing: 2px; color: var(--accent) }
.cc-scope .st.bad { color: var(--bad) }
.cc-scope .hull { fill: var(--accent-soft); stroke: var(--accent); stroke-width: 2 }
.cc-scope .cab { fill: none; stroke: var(--text); stroke-width: 2 }
.cc-scope .post { stroke: var(--muted); stroke-width: 4 }
.cc-scope .door { fill: var(--panel-2); stroke: var(--text); stroke-width: 3 }
.cc-scope .tank { height: 130px; margin-top: 10px; border: 2px solid var(--line); border-top: 0; border-radius: 0 0 8px 8px; display: flex; align-items: flex-end }
.cc-scope .water { width: 100%; background: var(--accent-soft); border-top: 2px solid var(--accent) }
.cc-scope .low { height: 28% }
.cc-scope .high { height: 86% }

.cc-scope .card { width: 300px; padding: 16px 18px; border: 1px solid var(--line); border-radius: 12px; background: var(--panel); font-family: var(--font-mono); color: var(--text) }
.cc-scope .hd { display: flex; justify-content: space-between; font-size: 15px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase }
.cc-scope .ok { color: var(--accent) }
.cc-scope .no { color: var(--bad) }
.cc-scope .row { display: flex; justify-content: space-between; margin-top: 10px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 8px; background: var(--panel-2); font-size: 13px; letter-spacing: 1px }
.cc-scope .pill { padding: 14px 22px; border: 1px solid var(--line); border-radius: 40px; background: var(--panel); font-family: var(--font-mono); font-size: 17px; color: var(--text) }
.cc-scope .cyl { fill: var(--panel); stroke: var(--line); stroke-width: 2 }
.cc-scope .rim { fill: none; stroke: var(--muted); stroke-width: 2 }
